// src/lib/rechner/dachpacht.js
//
// Dachpacht-Rechner: Was bringt eine große Dachfläche als PV-Standort?
// Reine Logik ohne React (Rechner, Seiten-Beispiele und Selbsttest nutzen
// dieselben Zahlen). Alle Standardwerte aus src/lib/invest/markt.js.
//
// Methodik (bewusst einfach und offen gelegt):
//  - Leistung = Dachfläche / m² je kWp der Dachart (brutto inkl. Abständen)
//  - Ertrag = Regionsertrag × Dachartfaktor × Ausrichtungsfaktor (nur
//    geneigte Dächer), Degradation p. a.
//  - Pachtspanne je Jahr aus €/m² (Hauptmaß) und Plausibilisierung über
//    €/kWp sowie den Anteil an den Stromerlösen (Volleinspeisung Dach)
//  - Drei Wege über die Laufzeit, nominal und als Barwert:
//      A) Dachpacht fest (kein Kapital, kein Betriebsrisiko)
//      B) Pacht + Strombezug vom eigenen Dach (On-Site-PPA): reduzierte
//         Pacht + Ersparnis = Eigenverbrauch × (Netzstrompreis − PPA-Preis)
//      C) Eigeninvestition: Investition, Eigenverbrauch zum Netzstrompreis,
//         Überschuss zur Einspeisevergütung, Betriebskosten mit Inflation
//  - Einmalzahlung = Barwert der Jahrespacht zum Betreiber-Diskontsatz

import { DACH, FREIFLAECHE, FINANZIERUNG, STROM, regionById, npv, irr } from "../invest/markt.js";

export const NETZSTROM_CT = Math.round(STROM.bestandteile.reduce((s, b) => s + b.ct, 0) * 10) / 10;

export const STANDARD = {
  m2: 5000,
  dachart: "trapez",
  ausrichtung: "sued",
  regionId: "de-sued",
  laufzeit: DACH.laufzeit,
  pachtProM2: DACH.pachtProM2.mittel,
  strompreisCt: NETZSTROM_CT,
  eigenverbrauch: DACH.eigenverbrauch.standard,
  ppaCt: DACH.ppaVorOrtCt.mittel,
  capexKwp: DACH.capexProKwp.mittel,
  opexKwp: DACH.opexProKwp,
  einspeiseCt: DACH.ueberschussCt,
  diskont: FINANZIERUNG.diskont,
  sanierung: false,
};

export const dachartById = (id) => DACH.dacharten.find((d) => d.id === id) || DACH.dacharten[0];
export const ausrichtungById = (id) => DACH.ausrichtung.find((a) => a.id === id) || DACH.ausrichtung[0];

/** Barwert einer konstanten Jahreszahlung (nachschüssig) */
export const rentenbarwert = (betrag, zins, jahre) => (zins === 0 ? betrag * jahre : (betrag * (1 - Math.pow(1 + zins, -jahre))) / zins);

export function rechneDach(eingabe = {}) {
  const e = { ...STANDARD, ...eingabe };
  const dach = dachartById(e.dachart);
  const region = regionById(e.regionId);
  const sanierungKosten = e.m2 * DACH.sanierungProM2.mittel;

  if (!dach.belegbar) {
    return { eingabe: e, dach, region, belegbar: false, sanierungKosten };
  }

  const geneigt = e.dachart !== "flach";
  const ausrichtung = geneigt ? ausrichtungById(e.ausrichtung) : { id: "ostWest", label: "Ost/West aufgeständert", faktor: 1 };
  const kwp = e.m2 / dach.m2ProKwp;
  const spezErtrag = region.ertrag * dach.ertragFaktor * ausrichtung.faktor;
  const kwhJahr1 = kwp * spezErtrag;
  const n = e.laufzeit;

  // Pachtspanne je Jahr
  const pachtSpanne = {
    min: e.m2 * DACH.pachtProM2.min,
    mittel: e.m2 * DACH.pachtProM2.mittel,
    max: e.m2 * DACH.pachtProM2.max,
  };
  const pachtJahr = e.m2 * e.pachtProM2;
  const pachtProKwp = pachtJahr / kwp;
  const erloesVoll = (kwhJahr1 * DACH.eegDachCt) / 100;
  const pachtAnteilErloes = erloesVoll > 0 ? pachtJahr / erloesVoll : null;
  const einmalzahlung = rentenbarwert(pachtJahr, DACH.einmalDiskont, n);

  // Jahreswerte der drei Wege
  const capex = kwp * e.capexKwp;
  const jahre = [];
  let sumA = 0;
  let sumB = 0;
  let sumC = -capex;
  for (let t = 1; t <= n; t++) {
    const kwh = kwhJahr1 * Math.pow(1 - FREIFLAECHE.degradation, t - 1);
    const eigen = kwh * e.eigenverbrauch;
    const ueberschuss = kwh - eigen;
    const a = pachtJahr;
    const bPacht = pachtJahr * DACH.ppaPachtAnteil;
    const bErsparnis = (eigen * Math.max(e.strompreisCt - e.ppaCt, 0)) / 100;
    const b = bPacht + bErsparnis;
    const cErsparnis = (eigen * e.strompreisCt) / 100;
    const cEinspeisung = (ueberschuss * e.einspeiseCt) / 100;
    const cOpex = kwp * e.opexKwp * Math.pow(1 + FREIFLAECHE.inflation, t - 1);
    const c = cErsparnis + cEinspeisung - cOpex;
    sumA += a;
    sumB += b;
    sumC += c;
    jahre.push({ jahr: t, kwh, eigen, ueberschuss, a, b, bPacht, bErsparnis, c, cErsparnis, cEinspeisung, cOpex, sumA, sumB, sumC });
  }

  const cfA = [0, ...jahre.map((j) => j.a)];
  const cfB = [0, ...jahre.map((j) => j.b)];
  const cfC = [-capex, ...jahre.map((j) => j.c)];

  let amortisation = null;
  let kum = -capex;
  for (const j of jahre) {
    const vorher = kum;
    kum += j.c;
    if (amortisation == null && kum >= 0 && j.c > 0) amortisation = j.jahr - 1 + -vorher / j.c;
  }

  const wege = {
    pacht: { id: "pacht", label: "Dachpacht", jahr1: jahre[0].a, summe: sumA, barwert: npv(e.diskont, cfA), invest: 0, irr: null },
    ppa: { id: "ppa", label: "Pacht + Dachstrom (PPA)", jahr1: jahre[0].b, summe: sumB, barwert: npv(e.diskont, cfB), invest: 0, irr: null },
    eigen: { id: "eigen", label: "Eigeninvestition", jahr1: jahre[0].c, summe: sumC, barwert: npv(e.diskont, cfC), invest: capex, irr: irr(cfC), amortisation },
  };

  return {
    eingabe: e,
    belegbar: true,
    dach,
    region,
    ausrichtung,
    kwp,
    spezErtrag,
    kwhJahr1,
    pachtSpanne,
    pachtJahr,
    pachtProKwp,
    pachtAnteilErloes,
    erloesVoll,
    einmalzahlung,
    capex,
    jahre,
    wege,
    sanierungKosten,
    /** Wie viele Jahre Pacht entspricht die Dachsanierung? */
    sanierungInPachtjahren: pachtJahr > 0 ? sanierungKosten / pachtJahr : null,
  };
}

/* ------------------------------------------------------------------ */
/* Selbsttest: node src/lib/rechner/dachpacht.js                       */
/* ------------------------------------------------------------------ */

export function selbsttest() {
  const fehler = [];
  const pruefe = (ok, text) => {
    if (!ok) fehler.push(text);
  };

  const r = rechneDach({ m2: 6000, dachart: "trapez", ausrichtung: "sued", regionId: "de-sued", pachtProM2: 2 });
  pruefe(Math.abs(r.kwp - 1000) < 1e-9, "6.000 m² Trapez / 6 m² je kWp = 1.000 kWp");
  pruefe(Math.abs(r.spezErtrag - 1100 * 0.95) < 1e-9, "Süd-Trapez in Süddeutschland = 1.045 kWh/kWp");
  pruefe(Math.abs(r.pachtJahr - 12000) < 1e-9, "Pacht 2 €/m² × 6.000 m² = 12.000 €/Jahr");
  pruefe(Math.abs(r.pachtProKwp - 12) < 1e-9, "entspricht 12 €/kWp");
  pruefe(r.pachtAnteilErloes > 0.08 && r.pachtAnteilErloes < 0.2, `Pacht als Erlösanteil plausibel (ist ${(r.pachtAnteilErloes * 100).toFixed(1)} %)`);
  pruefe(Math.abs(r.wege.pacht.summe - 12000 * DACH.laufzeit) < 1e-6, "Summe Pacht = Jahrespacht × Laufzeit");
  pruefe(r.einmalzahlung < r.wege.pacht.summe && r.einmalzahlung > 12000 * 10, "Einmalzahlung zwischen 10-facher Jahrespacht und Summe");
  pruefe(r.jahre.length === DACH.laufzeit, "Jahresreihe über die Laufzeit");
  pruefe(r.wege.eigen.irr != null && r.wege.eigen.irr > 0.03 && r.wege.eigen.irr < 0.25, `Eigeninvestition IRR plausibel (ist ${((r.wege.eigen.irr || 0) * 100).toFixed(1)} %)`);
  pruefe(r.wege.ppa.summe > r.wege.pacht.summe * DACH.ppaPachtAnteil, "PPA-Weg bringt mehr als die reduzierte Pacht");

  const flach = rechneDach({ m2: 7000, dachart: "flach", ausrichtung: "nord" });
  pruefe(Math.abs(flach.kwp - 1000) < 1e-9, "Flachdach 7 m² je kWp");
  pruefe(flach.ausrichtung.faktor === 1, "Flachdach ignoriert die Dachausrichtung (Ost/West aufgeständert)");

  const nord = rechneDach({ m2: 6000, ausrichtung: "nord" });
  pruefe(nord.kwhJahr1 < r.kwhJahr1, "Nord-Dach erzeugt weniger");

  const asbest = rechneDach({ m2: 6000, dachart: "faserzement" });
  pruefe(asbest.belegbar === false && asbest.sanierungKosten > 0, "Faserzement nicht belegbar, Sanierungskosten ausgewiesen");

  const ohneEv = rechneDach({ m2: 6000, eigenverbrauch: 0 });
  pruefe(Math.abs(ohneEv.wege.ppa.summe - ohneEv.wege.pacht.summe * DACH.ppaPachtAnteil) < 1e-6, "ohne Eigenverbrauch: PPA-Weg = reduzierte Pacht");
  const teuer = rechneDach({ m2: 6000, strompreisCt: 30 });
  pruefe(teuer.wege.eigen.barwert > r.wege.eigen.barwert, "höherer Netzstrompreis verbessert die Eigeninvestition");
  pruefe(Math.abs(rentenbarwert(100, 0, 10) - 1000) < 1e-9, "Rentenbarwert ohne Zins");

  return { fehler, beispiel: r };
}

if (typeof process !== "undefined" && process.argv?.[1] && /dachpacht\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
  const { fehler, beispiel: r } = selbsttest();
  const p = (x) => (x == null ? "–" : `${(x * 100).toFixed(1)} %`);
  console.log(
    `Beispiel 6.000 m² Trapez Süd, Süddeutschland: ${Math.round(r.kwp)} kWp, ${Math.round(r.kwhJahr1 / 1000)} MWh/Jahr, Pacht ${Math.round(r.pachtJahr)} €/Jahr ` +
      `(${p(r.pachtAnteilErloes)} der Erlöse), Einmalzahlung ${Math.round(r.einmalzahlung)} €, Eigeninvest IRR ${p(r.wege.eigen.irr)}, Amortisation ${r.wege.eigen.amortisation?.toFixed(1)} J.`
  );
  console.log(`Barwerte: Pacht ${Math.round(r.wege.pacht.barwert)} €, PPA ${Math.round(r.wege.ppa.barwert)} €, Eigen ${Math.round(r.wege.eigen.barwert)} €`);
  if (fehler.length) {
    console.error("FEHLER:\n- " + fehler.join("\n- "));
    process.exit(1);
  }
  console.log("Selbsttest dachpacht.js: alle Prüfungen bestanden.");
}
// src/lib/rechner/carport.js
//
// Wirtschaftlichkeit eines Solarcarports mit Ladepunkten – reine Logik.
// Zwei Wege im Vergleich:
//  - Kauf: Das Unternehmen investiert selbst, spart den Netzstrompreis für den
//    selbst genutzten Solarstrom und verkauft den Überschuss.
//  - Contracting/PPA: Ein Contractor baut und betreibt die Anlage; das
//    Unternehmen kauft den Solarstrom vor Ort zu einem festen Preis.
//    Der Preis wird aus den Vollkosten des Contractors hergeleitet (Annuität
//    zur Renditeerwartung + Betrieb − Überschusserlöse) plus Aufschlag.
// Stand und Quellen der Werte: src/lib/invest/markt.js.

import { CARPORT, ERLOESE, FINANZIERUNG, FREIFLAECHE, STROM, ALLGEMEIN, regionById, annuitaet } from "../invest/markt.js";

export const STROMPREIS_STANDARD = Math.round(STROM.bestandteile.reduce((s, b) => s + b.ct, 0) * 10) / 10;

export const STANDARD = {
  stellplaetze: 60,
  regionId: "de-sued",
  strompreisCt: STROMPREIS_STANDARD,
  eigenverbrauch: 0.7,
  ac: 10,
  dc: 1,
  capexKwp: CARPORT.capexProKwp.mittel,
};

export function rechneCarport(eingabe = {}) {
  const e = { ...STANDARD, ...eingabe };
  const region = regionById(e.regionId);
  const kwp = e.stellplaetze * CARPORT.kwpProStellplatz;
  const spez = region.ertrag * CARPORT.ertragFaktor;
  const ertrag = kwp * spez; // kWh im ersten Jahr
  const eigenKwh = ertrag * e.eigenverbrauch;
  const ueberschussKwh = ertrag - eigenKwh;

  const investPv = kwp * e.capexKwp;
  const investLaden = e.ac * CARPORT.ladepunktAc + e.dc * CARPORT.ladepunktDc;
  const invest = investPv + investLaden;
  const opexPv = kwp * CARPORT.opexProKwp;

  const L = CARPORT.laufzeit;
  const deg = FREIFLAECHE.degradation;
  const infl = FREIFLAECHE.inflation;
  const einspeiseCt = ERLOESE.merchantCt;

  /* --- Kauf ---------------------------------------------------------- */
  const kaufJahre = [];
  let kum = -invest;
  let amortisation = null;
  for (let t = 1; t <= L; t++) {
    const f = Math.pow(1 - deg, t - 1);
    const p = Math.pow(1 + infl, t - 1);
    const ersparnis = (eigenKwh * f * e.strompreisCt * p) / 100;
    const einspeisung = (ueberschussKwh * f * einspeiseCt) / 100;
    const kosten = opexPv * p;
    const cf = ersparnis + einspeisung - kosten;
    const vorher = kum;
    kum += cf;
    if (amortisation == null && kum >= 0 && cf > 0) amortisation = t - 1 + -vorher / cf;
    kaufJahre.push({ jahr: t, ersparnis, einspeisung, kosten, cf, kumuliert: kum });
  }
  const kaufJahr1 = kaufJahre[0];
  const kaufSumme = kum; // Überschuss nach Laufzeit (nominal)

  /* --- Contracting --------------------------------------------------- */
  // Vollkosten des Contractors je Jahr: Annuität auf die PV-Investition +
  // Betrieb − Erlöse aus dem Überschuss. Umgelegt auf den vor Ort
  // gelieferten Strom, plus Aufschlag.
  const n = CARPORT.contractingJahre;
  // Kapitalkosten des Contractors: Mischzins aus Fremd- und Eigenkapital
  const rendite = FINANZIERUNG.fremdkapitalQuote * FINANZIERUNG.zins + (1 - FINANZIERUNG.fremdkapitalQuote) * FINANZIERUNG.diskont;
  const annu = annuitaet(investPv, rendite, n);
  const ueberschussErloes = (ueberschussKwh * einspeiseCt) / 100;
  // Mittelwerte über die Vertragslaufzeit (Degradation, Opex-Steigerung)
  let sumF = 0;
  let sumP = 0;
  for (let t = 1; t <= n; t++) {
    sumF += Math.pow(1 - deg, t - 1);
    sumP += Math.pow(1 + infl, t - 1);
  }
  const mittelF = sumF / n;
  const mittelP = sumP / n;
  const vollkosten = annu + opexPv * mittelP - ueberschussErloes * mittelF;
  const contractingCt = eigenKwh > 0 ? ((vollkosten * (1 + CARPORT.contractingMarge)) / (eigenKwh * mittelF)) * 100 : null;

  const conJahre = [];
  let conKum = -investLaden;
  for (let t = 1; t <= L; t++) {
    const f = Math.pow(1 - deg, t - 1);
    const p = Math.pow(1 + infl, t - 1);
    const imVertrag = t <= n;
    // nach Vertragsende: Anlage geht üblicherweise an den Kunden über (hier vereinfacht: kostenlose Übernahme)
    const ersparnis = imVertrag
      ? (eigenKwh * f * (e.strompreisCt * p - (contractingCt ?? 0))) / 100
      : (eigenKwh * f * e.strompreisCt * p) / 100 + (ueberschussKwh * f * einspeiseCt) / 100 - opexPv * p;
    conKum += ersparnis;
    conJahre.push({ jahr: t, ersparnis, kumuliert: conKum, imVertrag });
  }

  return {
    eingabe: e,
    region,
    kwp,
    spez,
    ertrag,
    eigenKwh,
    ueberschussKwh,
    flaecheM2: e.stellplaetze * CARPORT.stellplatzM2,
    invest: { pv: investPv, laden: investLaden, summe: invest },
    opexPv,
    kauf: {
      jahre: kaufJahre,
      ersparnisJahr1: kaufJahr1.ersparnis,
      einspeisungJahr1: kaufJahr1.einspeisung,
      nettoJahr1: kaufJahr1.cf,
      amortisation,
      ueberschuss: kaufSumme,
    },
    contracting: {
      preisCt: contractingCt,
      jahre: conJahre,
      ersparnisJahr1: conJahre[0].ersparnis,
      invest: investLaden,
      ueberschuss: conKum,
      lohntSich: contractingCt != null && contractingCt < e.strompreisCt,
    },
    lcoeCt: ertrag > 0 ? ((annuitaet(investPv, rendite, L) + opexPv * mittelP) / (ertrag * mittelF)) * 100 : null,
    kapitalkosten: rendite,
    co2Tonnen: (ertrag * ALLGEMEIN.co2KgProKwh) / 1000,
    ladeleistungKw: e.ac * 11 + e.dc * 100,
  };
}

/* ------------------------------------------------------------------ */
/* Selbsttest: node src/lib/rechner/carport.js                         */
/* ------------------------------------------------------------------ */

export function selbsttest() {
  const fehler = [];
  const pruefe = (ok, text) => {
    if (!ok) fehler.push(text);
  };
  const r = rechneCarport({ stellplaetze: 100, regionId: "de-sued", strompreisCt: 20, eigenverbrauch: 0.7, ac: 0, dc: 0 });
  pruefe(Math.abs(r.kwp - 260) < 1e-9, "100 Stellplätze × 2,6 kWp = 260 kWp");
  pruefe(Math.abs(r.ertrag - 260 * 1100 * 0.93) < 1, "Ertrag = kWp × Regionsertrag × Carport-Faktor");
  pruefe(Math.abs(r.invest.summe - 260 * 1350) < 1, "Invest ohne Ladepunkte = kWp × Capex");
  pruefe(r.kauf.amortisation > 5 && r.kauf.amortisation < 15, `Amortisation plausibel 5–15 J. (ist ${r.kauf.amortisation?.toFixed(1)})`);
  pruefe(r.contracting.preisCt > 10 && r.contracting.preisCt < 25, `Contracting-Preis plausibel (ist ${r.contracting.preisCt?.toFixed(1)} ct)`);
  const mehrEv = rechneCarport({ stellplaetze: 100, strompreisCt: 20, eigenverbrauch: 0.95, ac: 0, dc: 0 });
  pruefe(mehrEv.kauf.amortisation < r.kauf.amortisation, "mehr Eigenverbrauch → schnellere Amortisation");
  pruefe(mehrEv.contracting.preisCt < r.contracting.preisCt, "mehr Eigenverbrauch → günstigerer Contracting-Preis");
  const lade = rechneCarport({ stellplaetze: 100, ac: 10, dc: 2 });
  pruefe(Math.abs(lade.invest.laden - (10 * 2500 + 2 * 45000)) < 1, "Ladepunkte-Invest");
  pruefe(rechneCarport({ eigenverbrauch: 0 }).contracting.preisCt == null, "ohne Eigenverbrauch kein Contracting-Preis");
  return { fehler, beispiel: r };
}

if (typeof process !== "undefined" && process.argv?.[1] && /carport\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
  const { fehler, beispiel: r } = selbsttest();
  console.log(
    `Beispiel 100 Stellplätze: ${Math.round(r.kwp)} kWp, ${Math.round(r.ertrag)} kWh, Invest ${Math.round(r.invest.summe)} €, ` +
      `Amortisation ${r.kauf.amortisation?.toFixed(1)} J., Contracting ${r.contracting.preisCt?.toFixed(1)} ct, LCOE ${r.lcoeCt?.toFixed(1)} ct`
  );
  if (fehler.length) {
    console.error("FEHLER:\n- " + fehler.join("\n- "));
    process.exit(1);
  }
  console.log("Selbsttest carport.js: alle Prüfungen bestanden.");
}
183:   * Marktübliche Spannen der Projektfinanzierung PV im DACH-Raum – eigene Einschätzung aus veröffentlichten
231:  /** Übliche Pacht für Freiflächen-PV in €/ha und Jahr (DACH, 2025/26) */
251:   * marktüblicher Vertragspunkte (DACH, 2025/26), keine Rechtsberatung:
313:/* Solarcarports & Parkflächen                                         */
316:export const CARPORT = {
476: * je Entwicklungsstand, DACH 2025/26 – breite Spannen, stark abhängig von
498:/* Energiegemeinschaften DACH                                          */
646:/* Dach-PV: Dachpacht auf Gewerbe-, Hallen-, Agrar- und Logistikdächern */
650: * Orientierungswerte für die Verpachtung großer Dachflächen (ab ca. 1.000 m²)
654: *  - Pachtspannen: Marktübersichten von Dachvermittlern und Ratgebern nennen
659: *  - Zuschläge Dach (Ausschreibung zweites Segment, Gebäude/Lärmschutz):
662: *  - Investition, Betriebskosten, Dachsanierung: eigene Marktbeobachtung der
665:export const DACH = {
666:  /** Sinnvolle Mindestgröße für Dachpacht (darunter lohnt sich ein Fremdbetrieb selten) */
669:   * Dacharten: Dachfläche brutto je kWp (inkl. Randabstände, Brandschutz-
670:   * streifen, Dachaufbauten), Ertragsfaktor relativ zur optimalen
673:  dacharten: [
674:    { id: "trapez", label: "Trapezblech", sub: "geneigt, Aufdach", m2ProKwp: 6, ertragFaktor: 0.95, belegbar: true, lastKgM2: "ca. 12–15 kg/m²" },
676:    { id: "flach", label: "Flachdach", sub: "Folie/Bitumen, Ost/West", m2ProKwp: 7, ertragFaktor: 0.9, belegbar: true, lastKgM2: "ca. 15–25 kg/m² mit Ballast" },
686:  /** Dachpacht fest in € je m² Dachfläche und Jahr */
688:  /** Dachpacht in € je installiertem kWp und Jahr */
692:  /** Übliche Laufzeit Dachnutzungsvertrag (Jahre) und Option */
697:  /** Investition Gewerbedach 300 kWp – 2 MWp schlüsselfertig ohne Dachsanierung, €/kWp */
701:  /** Zuschläge Ausschreibung Dach (zweites Segment, Pflicht in der Regel ab 1 MWp), ct/kWh */
707:  /** Rechenwert Volleinspeisung Dach (Mittel der Zuschläge 2025, gerundet) */
708:  eegDachCt: 9.3,
